// rekap-laporan.mjs — Pembangun laporan Rekap Publikasi Harian UPT (ZonaPas).
//
// Dipakai halaman /portal/aplikasi-pendukung/app-rekap-publish/ :
//   import { buildDocx, buildPdf } from '/rekap-laporan.mjs';
//   const docx = await buildDocx(data);   // -> Blob DOCX
//   const pdf  = await buildPdf(data);    // -> Blob PDF
//   data = { tanggal: 'YYYY-MM-DD', rows: [{tanggal, upt, judul, platform, url}],
//            nihil: ['Bapas Kelas I Bengkulu'] | [{tanggal, upt}] }
// Kirim WA: unggah blob ke POST /redaksi/api/rekap/file lalu buka
//   https://api.whatsapp.com/send?text=<pesan berisi tautan unduh>
// Tautan unduh: https://zonapas.web.id/redaksi/api/rekap/file?token=<token>
//
// Acuan format: template resmi Kanwil (Laporan_04_November_2026-2_16_sgdw.docx,
// "hukum verbatim") dan laporan jadi 7 Nov 2026 yang sudah disetujui.
// DOCX dibangun sebagai ZIP+XML dari nol (entri stored, tanpa dependensi)
// meniru struktur template: kop + logo Kemenimipas, A–D, tabel rekapitulasi
// 11x5, rincian per UPT a/b/c/d, "Nihil", tanda tangan MASJUNO, pukul 20.00
// WIB, seluruh isi Arial 11, tautan aktif (hyperlink + relasi).
// PDF dibangun dari nol juga (tanpa pustaka): A4, margin dan spasi yang sama,
// Helvetica sebagai pengganti Arial (lihat catatan fidelity di bawah).
// TIDAK ada CDN / dependensi runtime; logo Kemenimipas tertanam base64.
//
// Catatan fidelity (jujur):
//  - PDF memakai font inti Helvetica/Helvetica-Bold, bukan Arial: Arial
//    tidak tersedia sebagai file font yang bisa ditanam; Helvetica adalah
//    pengganti metrik-nya (lebar huruf hampir identik; di Linux ter-render
//    sebagai Liberation Sans, sama seperti PDF 5/6 Nov 2026 dari aplikasi
//    Rekap lama yang memakai "Arial 11 (ter-render Liberation Sans)").
//  - PDF tidak memakai penomoran halaman / header-footer: template DOCX
//    juga tidak punya nomor halaman maupun header/footer.
//  - Karakter di luar WinAnsi (mis. emoji di judul) dihilangkan di PDF
//    (DOCX mempertahankannya). Tanda baca umum (• – — " " … é) dipetakan.
//  - DOCX: nomor rsid/paraId tidak disalin dari template (Word tidak
//    memerlukannya); struktur, gaya, spasi, warna, dan indentasi disalin.

export const REKAP_UPT_LAPORAN = ["Kanwil Ditjenpas Bengkulu", "Lapas Kelas IIA Bengkulu", "Lapas Kelas IIA Curup", "Lapas Kelas IIB Arga Makmur", "Lapas Perempuan Kelas IIB Bengkulu", "Bapas Kelas I Bengkulu", "LPKA Kelas II Bengkulu", "Rutan Kelas IIB Bengkulu", "Rutan Kelas IIB Manna"];
export const REKAP_JUDUL_KOSONG = "Publikasi (tanpa judul di laporan)";

// Nama UPT seperti tertulis di DOKUMEN laporan (template): Kanwil ditulis
// lengkap "Kantor Wilayah Direktorat Jenderal Pemasyarakatan Bengkulu"
// di tabel rekapitulasi + judul rincian; 8 UPT lain sama dengan nama baku.
export const NAMA_LAPORAN = { "Kanwil Ditjenpas Bengkulu": "Kantor Wilayah Direktorat Jenderal Pemasyarakatan Bengkulu" };
export function namaLaporan(upt) { return NAMA_LAPORAN[upt] || upt; }
// Diisi base64 asli saat penulisan file (placeholder diganti skrip build).
const LOGO_JPG_BASE64 = "";

const HARI_ID = ["Minggu", "Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu"];
const BULAN_ID = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];

export function tanggalIndonesia(iso) {
  const [y, m, d] = String(iso || "").split("-").map(Number);
  const dt = new Date(Date.UTC(y, (m || 1) - 1, d || 1));
  return `${HARI_ID[dt.getUTCDay()]}, ${d} ${BULAN_ID[(m || 1) - 1]} ${y}`;
}
export function tanggalIndonesiaTanpaHari(iso) {
  const [y, m, d] = String(iso || "").split("-").map(Number);
  return `${d} ${BULAN_ID[(m || 1) - 1]} ${y}`;
}
export function namaFileLaporan(tanggal, ext) {
  const [y, m, d] = String(tanggal || "").split("-");
  return `${d}_${m}_${y}_Laporan_Publikasi_Harian_Kanwil_Ditjenpas_Bengkulu.${ext}`;
}

// Hitung rekap per UPT dari rows + penanda nihil. Judul di laporan adalah
// judul UNIK per UPT (urutan kemunculan pertama); tautan = semua baris.
export function hitungRekap(data) {
  const tanggal = data.tanggal || data.date || "";
  const rows = (data.rows || []).filter((r) => !tanggal || !r.tanggal || r.tanggal === tanggal);
  const nihilSet = new Set((data.nihil || []).map((n) => (typeof n === "string" ? n : n.upt)));
  const perUpt = REKAP_UPT_LAPORAN.map((nama) => {
    const rs = rows.filter((r) => r.upt === nama);
    const sosial = rs.filter((r) => r.platform !== "Website / Media Online").length;
    const massa = rs.length - sosial;
    const judulUnik = [];
    for (const r of rs) {
      const j = String(r.judul || "").trim() || REKAP_JUDUL_KOSONG;
      if (!judulUnik.includes(j)) judulUnik.push(j);
    }
    return { nama, rows: rs, sosial, massa, jumlah: rs.length, nihil: rs.length === 0 && nihilSet.has(nama), judul: rs.length ? judulUnik : ["Nihil"], tautan: rs.length ? rs.map((r) => r.url) : ["Nihil"] };
  });
  const total = perUpt.reduce((a, u) => ({ sosial: a.sosial + u.sosial, massa: a.massa + u.massa, jumlah: a.jumlah + u.jumlah }), { sosial: 0, massa: 0, jumlah: 0 });
  return { tanggal, perUpt, total };
}

function escXml(s) {
  return String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

// ---------- ZIP (entri stored) ----------
const CRC_TABEL = (() => {
  const t = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    t[n] = c >>> 0;
  }
  return t;
})();
function crc32(u8) {
  let c = 0xffffffff;
  for (let i = 0; i < u8.length; i++) c = CRC_TABEL[(c ^ u8[i]) & 0xff] ^ (c >>> 8);
  return (c ^ 0xffffffff) >>> 0;
}
function zipStored(files) {
  // files: [[nama, Uint8Array|string]] — entri stored (tanpa kompresi).
  const enc = new TextEncoder();
  const lokal = [];
  const sentral = [];
  let offset = 0;
  for (const [nama, isi] of files) {
    const namaB = enc.encode(nama);
    const data = typeof isi === "string" ? enc.encode(isi) : isi;
    const crc = crc32(data);
    const lh = new DataView(new ArrayBuffer(30));
    lh.setUint32(0, 0x04034b50, true);
    lh.setUint16(4, 20, true);
    lh.setUint16(6, 0x0800, true); // nama file UTF-8
    lh.setUint16(8, 0, true);
    lh.setUint16(10, 0, true);
    lh.setUint16(12, 0, true);
    lh.setUint32(14, crc, true);
    lh.setUint32(18, data.length, true);
    lh.setUint32(22, data.length, true);
    lh.setUint16(26, namaB.length, true);
    lh.setUint16(28, 0, true);
    lokal.push(lh.buffer, namaB, data);
    const ch = new DataView(new ArrayBuffer(46));
    ch.setUint32(0, 0x02014b50, true);
    ch.setUint16(4, 20, true);
    ch.setUint16(6, 20, true);
    ch.setUint16(8, 0x0800, true);
    ch.setUint16(10, 0, true);
    ch.setUint16(12, 0, true);
    ch.setUint16(14, 0, true);
    ch.setUint32(16, crc, true);
    ch.setUint32(20, data.length, true);
    ch.setUint32(24, data.length, true);
    ch.setUint16(28, namaB.length, true);
    ch.setUint16(30, 0, true);
    ch.setUint16(32, 0, true);
    ch.setUint16(34, 0, true);
    ch.setUint16(36, 0, true);
    ch.setUint32(38, 0, true);
    ch.setUint32(42, offset, true);
    sentral.push(ch.buffer, namaB);
    offset += 30 + namaB.length + data.length;
  }
  const awalSentral = offset;
  let ukuranSentral = 0;
  for (const b of sentral) ukuranSentral += b.byteLength;
  const akhir = new DataView(new ArrayBuffer(22));
  akhir.setUint32(0, 0x06054b50, true);
  akhir.setUint16(4, 0, true);
  akhir.setUint16(6, 0, true);
  akhir.setUint16(8, files.length, true);
  akhir.setUint16(10, files.length, true);
  akhir.setUint32(12, ukuranSentral, true);
  akhir.setUint32(16, awalSentral, true);
  akhir.setUint16(20, 0, true);
  const bagian = [...lokal, ...sentral, akhir.buffer];
  const total = bagian.reduce((a, b) => a + b.byteLength, 0);
  const out = new Uint8Array(total);
  let p = 0;
  for (const b of bagian) { out.set(new Uint8Array(b), p); p += b.byteLength; }
  return out;
}
function b64KeU8(b64) {
  const bin = atob(b64);
  const u8 = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return u8;
}

// ---------- DOCX ----------
const R_ARIAL = `<w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/></w:rPr>`;
const R_ARIAL_B = `<w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:b/></w:rPr>`;
const R_ARIAL_B_WARNA = `<w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:b/><w:color w:val="0A1F44"/></w:rPr>`;
const R_TAUTAN = `<w:rPr><w:rFonts w:ascii="Arial" w:hAnsi="Arial" w:cs="Arial"/><w:color w:val="1D4ED8"/><w:u w:val="single"/></w:rPr>`;
function pPr(spasi, tambahan = "") {
  return `<w:pPr><w:spacing ${spasi}/>${tambahan}</w:pPr>`;
}
function para(teks, ppr, rpr = R_ARIAL) {
  return `<w:p>${ppr}<w:r>${rpr}<w:t xml:space="preserve">${escXml(teks)}</w:t></w:r></w:p>`;
}
function paraJc(teks, jc, rpr = R_ARIAL_B, spasi = `w:after="20" w:line="276" w:lineRule="auto"`) {
  return `<w:p><w:pPr><w:spacing ${spasi}/><w:jc w:val="${jc}"/></w:pPr><w:r>${rpr}<w:t xml:space="preserve">${escXml(teks)}</w:t></w:r></w:p>`;
}
function paraJustify(teks, spasi = `w:after="160" w:line="276" w:lineRule="auto"`, tambahan = "") {
  return `<w:p><w:pPr><w:spacing ${spasi}/>${tambahan}<w:jc w:val="both"/></w:pPr><w:r>${R_ARIAL}<w:t xml:space="preserve">${escXml(teks)}</w:t></w:r></w:p>`;
}
function paraTabNomor(nomor, teks) {
  // Butir bernomor ala template: "1." + tab + isi, indent gantung.
  return `<w:p><w:pPr><w:tabs><w:tab w:val="left" w:pos="1080"/></w:tabs><w:spacing w:after="20" w:line="276" w:lineRule="auto"/><w:ind w:left="1080" w:hanging="360"/></w:pPr><w:r>${R_ARIAL}<w:t>${nomor}.</w:t></w:r><w:r><w:tab/></w:r><w:r>${R_ARIAL}<w:t xml:space="preserve">${escXml(teks)}</w:t></w:r></w:p>`;
}

