function bangunDocumentXml(data) {
  const hitung = hitungRekap(data);
  const tanggal = hitung.tanggal, total = hitung.total;
  const perUpt = hitung.perUpt.map((u) => ({ ...u, nama: namaLaporan(u.nama) }));
  const tglPanjang = tanggalIndonesia(tanggal);
  const tglSingkat = tanggalIndonesiaTanpaHari(tanggal);
  // Kumpulkan tautan unik (urutan kemunculan pertama) -> rId hyperlink.
  const tautanUnik = [];
  const idTautan = new Map();
  for (const u of perUpt) for (const t of u.tautan) {
    if (t === "Nihil") continue;
    if (!idTautan.has(t)) { idTautan.set(t, `rId${idTautan.size + 2}`); tautanUnik.push(t); }
  }
  const isi = [];
  // --- Kop: logo + nama instansi (tabel tanpa garis) ---
  isi.push(`<w:tbl><w:tblPr><w:tblW w:w="0" w:type="auto"/><w:tblInd w:w="10" w:type="dxa"/><w:tblBorders><w:top w:val="nil"/><w:left w:val="nil"/><w:bottom w:val="nil"/><w:right w:val="nil"/><w:insideH w:val="nil"/><w:insideV w:val="nil"/></w:tblBorders><w:tblCellMar><w:left w:w="10" w:type="dxa"/><w:right w:w="10" w:type="dxa"/></w:tblCellMar><w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/></w:tblPr><w:tblGrid><w:gridCol w:w="1500"/><w:gridCol w:w="8366"/></w:tblGrid><w:tr><w:tc><w:tcPr><w:tcW w:w="1500" w:type="dxa"/><w:vAlign w:val="center"/></w:tcPr><w:p><w:pPr><w:spacing w:after="0" w:line="276" w:lineRule="auto"/><w:jc w:val="center"/></w:pPr><w:r><w:rPr><w:noProof/></w:rPr><w:drawing><wp:inline distT="0" distB="0" distL="0" distR="0"><wp:extent cx="914400" cy="914400"/><wp:effectExtent l="0" t="0" r="0" b="0"/><wp:docPr id="1" name="Logo Kementerian"/><wp:cNvGraphicFramePr/><a:graphic xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"><a:graphicData uri="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:pic xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture"><pic:nvPicPr><pic:cNvPr id="1" name="logo-kemenimipas.jpg"/><pic:cNvPicPr/></pic:nvPicPr><pic:blipFill><a:blip r:embed="rId1"/><a:stretch><a:fillRect/></a:stretch></pic:blipFill><pic:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="914400" cy="914400"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></pic:spPr></pic:pic></a:graphicData></a:graphic></wp:inline></w:drawing></w:r></w:p></w:tc><w:tc><w:tcPr><w:tcW w:w="8366" w:type="dxa"/><w:vAlign w:val="center"/></w:tcPr>${paraJc("KEMENTERIAN IMIGRASI DAN PEMASYARAKATAN REPUBLIK INDONESIA", "center", R_ARIAL_B_WARNA)}${paraJc("DIREKTORAT JENDERAL PEMASYARAKATAN", "center", R_ARIAL_B_WARNA)}${paraJc("KANTOR WILAYAH BENGKULU", "center", R_ARIAL_B_WARNA)}${paraJc("Jl. Batang Hari No.17, Kec. Ratu Agung, Kota Bengkulu", "center", R_ARIAL)}${paraJc("Pos-el : bengkuluditjenpas@gmail.com", "center", R_ARIAL)}</w:tc></w:tr></w:tbl>`);
  isi.push(`<w:p/>`);
  // --- Judul laporan ---
  for (const baris of ["LAPORAN", "TENTANG", "DATA HARIAN HASIL RILIS DAN PUBLIKASI MEDIA SOSIAL", "UNIT PELAKSANA TEKNIS PEMASYARAKATAN DI LINGKUNGAN", "KANTOR WILAYAH DIREKTORAT JENDERAL PEMASYARAKATAN BENGKULU"]) {
    isi.push(paraJc(baris, "center", R_ARIAL_B));
  }
  const judulBagian = (teks) => `<w:p><w:pPr><w:spacing w:before="240" w:after="80" w:line="276" w:lineRule="auto"/></w:pPr><w:r>${R_ARIAL_B_WARNA}<w:t xml:space="preserve">${escXml(teks)}</w:t></w:r></w:p>`;
  const subJudul = (teks, kiri = "284") => `<w:p><w:pPr><w:spacing w:before="160" w:after="0" w:line="276" w:lineRule="auto"/><w:ind w:left="${kiri}"/></w:pPr><w:r>${R_ARIAL_B}<w:t xml:space="preserve">${escXml(teks)}</w:t></w:r></w:p>`;
  // --- A. PENDAHULUAN ---
  isi.push(judulBagian("A. PENDAHULUAN"));
  isi.push(paraJustify(TEKS_PENDAHULUAN));
  isi.push(subJudul("1. Umum"));
  isi.push(paraJustify(TEKS_UMUM, `w:after="160" w:line="276" w:lineRule="auto"`));
  isi.push(subJudul("2. Maksud dan Tujuan"));
  isi.push(paraJustify(TEKS_MAKSUD));
  TUJUAN.forEach((t, i) => {
    isi.push(`<w:p><w:pPr><w:spacing w:after="20" w:line="276" w:lineRule="auto"/><w:ind w:left="851" w:hanging="284"/><w:jc w:val="both"/></w:pPr><w:r>${R_ARIAL}<w:t>${i + 1}.</w:t></w:r><w:r><w:tab/></w:r><w:r>${R_ARIAL}<w:t xml:space="preserve">${escXml(t)}</w:t></w:r></w:p>`);
  });
  isi.push(subJudul("3. Ruang Lingkup"));
  isi.push(paraJustify(TEKS_RUANG_LINGKUP, `w:after="20" w:line="276" w:lineRule="auto"`));
  isi.push(`<w:p><w:pPr><w:spacing w:after="20" w:line="276" w:lineRule="auto"/><w:ind w:left="720"/></w:pPr><w:r>${R_ARIAL}<w:t>• Hari/tanggal</w:t></w:r><w:r><w:tab/></w:r><w:r>${R_ARIAL}<w:t xml:space="preserve">: ${escXml(tglPanjang)}</w:t></w:r></w:p>`);
  isi.push(`<w:p><w:pPr><w:spacing w:after="20" w:line="276" w:lineRule="auto"/><w:ind w:left="720"/></w:pPr><w:r>${R_ARIAL}<w:t>• Pukul</w:t></w:r><w:r><w:tab/></w:r><w:r><w:tab/></w:r><w:r>${R_ARIAL}<w:t xml:space="preserve">: 20.00 WIB</w:t></w:r></w:p>`);
  // --- B. KEGIATAN YANG DILAKSANAKAN ---
  isi.push(judulBagian("B. KEGIATAN YANG DILAKSANAKAN"));
  isi.push(paraJustify(TEKS_KEGIATAN_1));
  isi.push(paraJustify(TEKS_KEGIATAN_2));
  isi.push(paraJustify(TEKS_KEGIATAN_3));
  // --- C. HASIL YANG DICAPAI ---
  isi.push(judulBagian("C. HASIL YANG DICAPAI"));
  isi.push(`<w:p><w:pPr><w:spacing w:before="160" w:after="60" w:line="276" w:lineRule="auto"/><w:ind w:left="142"/></w:pPr><w:r>${R_ARIAL_B}<w:t>1. Rekapitulasi Publikasi</w:t></w:r></w:p>`);
  isi.push(`<w:p><w:pPr><w:spacing w:after="60" w:line="276" w:lineRule="auto"/><w:ind w:firstLine="567"/><w:jc w:val="both"/></w:pPr><w:r>${R_ARIAL}<w:t>Jumlah publikasi pada hari pelaporan adalah sebagai berikut:</w:t></w:r></w:p>`);
  const barisHitung = (label, n) => `<w:p><w:pPr><w:tabs><w:tab w:val="left" w:pos="1985"/></w:tabs><w:spacing w:after="20" w:line="276" w:lineRule="auto"/><w:ind w:left="567"/></w:pPr><w:r>${R_ARIAL}<w:t>${label}</w:t></w:r><w:r><w:tab/></w:r><w:r>${R_ARIAL}<w:t xml:space="preserve">: ${n} publikasi</w:t></w:r></w:p>`;
  isi.push(barisHitung("Media Sosial", total.sosial));
  isi.push(barisHitung("Media Massa", total.massa));
  isi.push(barisHitung("Jumlah", total.jumlah));
  isi.push(paraJustify("Rincian jumlah publikasi per satuan kerja disajikan dalam tabel berikut:", `w:after="60" w:line="276" w:lineRule="auto"`, `<w:ind w:firstLine="567"/>`));
  // Tabel rekapitulasi 11x5.
  const sel = (teks, { tebal = false, tengah = false, isi = false, lebar = 0 } = {}) => {
    const rpr = tebal ? R_ARIAL_B_WARNA : R_ARIAL;
    const jc = tengah ? `<w:jc w:val="center"/>` : "";
    const shd = isi ? `<w:shd w:val="clear" w:color="auto" w:fill="E6ECF5"/>` : "";
    return `<w:tc><w:tcPr><w:tcW w:w="${lebar}" w:type="dxa"/>${shd}<w:vAlign w:val="center"/></w:tcPr><w:p><w:pPr><w:spacing w:before="20" w:after="20" w:line="276" w:lineRule="auto"/>${jc}</w:pPr><w:r>${rpr}<w:t xml:space="preserve">${escXml(teks)}</w:t></w:r></w:p></w:tc>`;
  };
  const barisTabel = (cells, header = false) => `<w:tr>${header ? "<w:trPr><w:tblHeader/></w:trPr>" : ""}${cells}</w:tr>`;
  let tabel = `<w:tbl><w:tblPr><w:tblW w:w="8871" w:type="dxa"/><w:tblInd w:w="152" w:type="dxa"/><w:tblBorders><w:top w:val="single" w:sz="4" w:space="0" w:color="8A99B3"/><w:left w:val="single" w:sz="4" w:space="0" w:color="8A99B3"/><w:bottom w:val="single" w:sz="4" w:space="0" w:color="8A99B3"/><w:right w:val="single" w:sz="4" w:space="0" w:color="8A99B3"/><w:insideH w:val="single" w:sz="4" w:space="0" w:color="8A99B3"/><w:insideV w:val="single" w:sz="4" w:space="0" w:color="8A99B3"/></w:tblBorders><w:tblCellMar><w:left w:w="10" w:type="dxa"/><w:right w:w="10" w:type="dxa"/></w:tblCellMar><w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/></w:tblPr><w:tblGrid><w:gridCol w:w="556"/><w:gridCol w:w="4264"/><w:gridCol w:w="1447"/><w:gridCol w:w="1447"/><w:gridCol w:w="1157"/></w:tblGrid>`;
  tabel += barisTabel(sel("No.", { tebal: true, tengah: true, isi: true, lebar: 556 }) + sel("Satuan Kerja", { tebal: true, isi: true, lebar: 4264 }) + sel("Media Sosial", { tebal: true, tengah: true, isi: true, lebar: 1447 }) + sel("Media Massa", { tebal: true, tengah: true, isi: true, lebar: 1447 }) + sel("Jumlah", { tebal: true, tengah: true, isi: true, lebar: 1157 }), true);
  perUpt.forEach((u, i) => {
    tabel += barisTabel(sel(String(i + 1), { tengah: true, lebar: 556 }) + sel(u.nama, { lebar: 4264 }) + sel(String(u.sosial), { tengah: true, lebar: 1447 }) + sel(String(u.massa), { tengah: true, lebar: 1447 }) + sel(String(u.jumlah), { tengah: true, lebar: 1157 }));
  });
  tabel += barisTabel(sel("", { lebar: 556 }) + sel("JUMLAH", { tebal: true, lebar: 4264 }) + sel(String(total.sosial), { tebal: true, tengah: true, lebar: 1447 }) + sel(String(total.massa), { tebal: true, tengah: true, lebar: 1447 }) + sel(String(total.jumlah), { tebal: true, tengah: true, lebar: 1157 }));
  tabel += `</w:tbl>`;
  isi.push(tabel);
  isi.push(`<w:p/>`);
  // --- 2. Rincian Publikasi Per Satuan Kerja ---
  isi.push(`<w:p><w:pPr><w:spacing w:after="0" w:line="276" w:lineRule="auto"/><w:ind w:left="142"/></w:pPr><w:r>${R_ARIAL_B}<w:t>2. Rincian Publikasi Per Satuan Kerja</w:t></w:r></w:p>`);
  perUpt.forEach((u, i) => {
    isi.push(`<w:p><w:pPr><w:spacing w:after="0" w:line="276" w:lineRule="auto"/><w:ind w:firstLine="284"/></w:pPr><w:r>${R_ARIAL_B_WARNA}<w:t>${i + 1}) </w:t></w:r><w:r>${R_ARIAL_B_WARNA}<w:t xml:space="preserve">${escXml(u.nama)}</w:t></w:r></w:p>`);
    const ab = (huruf, label, n) => `<w:p><w:pPr><w:spacing w:after="0" w:line="276" w:lineRule="auto"/><w:ind w:left="360"/></w:pPr><w:r>${R_ARIAL}<w:t xml:space="preserve">${huruf}. ${label} : ${n} publikasi</w:t></w:r></w:p>`;
    isi.push(ab("a", "Media Sosial", u.sosial));
    isi.push(ab("b", "Media Massa", u.massa));
    isi.push(`<w:p>${pPr(`w:after="20" w:line="276" w:lineRule="auto"`, `<w:ind w:left="360"/>`)}<w:r>${R_ARIAL}<w:t>c. Judul Publikasi :</w:t></w:r></w:p>`);
    u.judul.forEach((j, k) => isi.push(paraTabNomor(k + 1, j)));
    isi.push(`<w:p>${pPr(`w:after="20" w:line="276" w:lineRule="auto"`, `<w:ind w:left="360"/>`)}<w:r>${R_ARIAL}<w:t>d. Tautan Publikasi :</w:t></w:r></w:p>`);
    u.tautan.forEach((t, k) => {
      if (t === "Nihil") { isi.push(paraTabNomor(k + 1, "Nihil")); return; }
      isi.push(`<w:p><w:pPr><w:tabs><w:tab w:val="left" w:pos="1080"/></w:tabs><w:spacing w:after="20" w:line="276" w:lineRule="auto"/><w:ind w:left="1080" w:hanging="360"/></w:pPr><w:r>${R_ARIAL}<w:t>${k + 1}.</w:t></w:r><w:r><w:tab/></w:r><w:hyperlink r:id="${idTautan.get(t)}"><w:r>${R_TAUTAN}<w:t xml:space="preserve">${escXml(t)}</w:t></w:r></w:hyperlink></w:p>`);
    });
  });
  // --- D. PENUTUP ---
  isi.push(judulBagian("D. PENUTUP"));
  isi.push(paraJustify(TEKS_PENUTUP_1));
  isi.push(paraJustify(TEKS_PENUTUP_2));
  isi.push(`<w:p/>`);
  isi.push(`<w:tbl><w:tblPr><w:tblW w:w="3600" w:type="dxa"/><w:jc w:val="right"/><w:tblBorders><w:top w:val="nil"/><w:left w:val="nil"/><w:bottom w:val="nil"/><w:right w:val="nil"/><w:insideH w:val="nil"/><w:insideV w:val="nil"/></w:tblBorders><w:tblCellMar><w:left w:w="10" w:type="dxa"/><w:right w:w="10" w:type="dxa"/></w:tblCellMar><w:tblLook w:val="04A0" w:firstRow="1" w:lastRow="0" w:firstColumn="1" w:lastColumn="0" w:noHBand="0" w:noVBand="1"/></w:tblPr><w:tblGrid><w:gridCol w:w="3600"/></w:tblGrid><w:tr><w:trPr><w:jc w:val="right"/><w:cantSplit/></w:trPr><w:tc><w:tcPr><w:tcW w:w="3600" w:type="dxa"/></w:tcPr>${para(`Bengkulu, ${tglSingkat}`, pPr(`w:after="20" w:line="276" w:lineRule="auto"`))}${para("Kepala Kantor Wilayah,", pPr(`w:after="0" w:line="276" w:lineRule="auto"`))}<w:p>${pPr(`w:after="0" w:line="276" w:lineRule="auto"`)}</w:p>${para("ttd", pPr(`w:after="0" w:line="276" w:lineRule="auto"`))}<w:p>${pPr(`w:after="0" w:line="276" w:lineRule="auto"`)}</w:p>${para("MASJUNO", pPr(`w:after="0" w:line="276" w:lineRule="auto"`), R_ARIAL_B)}</w:tc></w:tr></w:tbl>`);
  isi.push(`<w:p/>`);
  const relsTautan = tautanUnik.map((t) => `<Relationship Id="${idTautan.get(t)}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="${escXml(t)}" TargetMode="External"/>`).join("");
  const documentXml = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<w:document xmlns:wpc="http://schemas.microsoft.com/office/word/2010/wordprocessingCanvas" xmlns:mc="http://schemas.openxmlformats.org/markup-compatibility/2006" xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" xmlns:m="http://schemas.openxmlformats.org/officeDocument/2006/math" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:wp14="http://schemas.microsoft.com/office/word/2010/wordprocessingDrawing" xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" xmlns:w10="urn:schemas-microsoft-com:office/word" xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:w14="http://schemas.microsoft.com/office/word/2010/wordml" xmlns:w15="http://schemas.microsoft.com/office/word/2012/wordml" xmlns:wpg="http://schemas.microsoft.com/office/word/2010/wordprocessingGroup" xmlns:wpi="http://schemas.microsoft.com/office/word/2010/wordprocessingInk" xmlns:wne="http://schemas.microsoft.com/office/word/2006/wordml" xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape" mc:Ignorable="w14 w15 wp14"><w:body>${isi.join("")}<w:sectPr><w:pgSz w:w="11906" w:h="16838"/><w:pgMar w:top="1020" w:right="1020" w:bottom="1020" w:left="1020" w:header="720" w:footer="720" w:gutter="0"/><w:cols w:space="720"/></w:sectPr></w:body></w:document>`;
  return { documentXml, relsTautan };
}

