export function buildDocx(data) {
  const { documentXml, relsTautan } = bangunDocumentXml(data);
  const { tanggal } = hitungRekap(data);
  const [y, m, d] = String(tanggal || "2026-01-01").split("-");
  const dibuat = `${y}-${m}-${d}T13:00:00Z`; // 20.00 WIB = 13.00 UTC
  const core = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>Laporan Publikasi Harian Kanwil Ditjenpas Bengkulu — ${escXml(tanggalIndonesiaTanpaHari(tanggal))}</dc:title><dc:creator>ZonaPas</dc:creator><cp:lastModifiedBy>ZonaPas</cp:lastModifiedBy><dcterms:created xsi:type="dcterms:W3CDTF">${dibuat}</dcterms:created><dcterms:modified xsi:type="dcterms:W3CDTF">${dibuat}</dcterms:modified></cp:coreProperties>`;
  const app = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties"><Application>ZonaPas</Application></Properties>`;
  const docRels = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/image1.jpg"/>${relsTautan}</Relationships>`;
  const zip = zipStored([
    ["[Content_Types].xml", DOCX_CONTENT_TYPES],
    ["_rels/.rels", DOCX_RELS],
    ["docProps/core.xml", core],
    ["docProps/app.xml", app],
    ["word/document.xml", documentXml],
    ["word/_rels/document.xml.rels", docRels],
    ["word/media/image1.jpg", b64KeU8(LOGO_JPG_BASE64)],
    ["word/styles.xml", DOCX_STYLES],
    ["word/fontTable.xml", DOCX_FONTTABLE],
    ["word/settings.xml", DOCX_SETTINGS],
    ["word/theme/theme1.xml", DOCX_THEME],
    ["word/webSettings.xml", DOCX_WEBSETTINGS],
  ]);
  return new Blob([zip], { type: "application/vnd.openxmlformats-officedocument.wordprocessingml.document" });
}

